  input clock, reset,
  input                                 rvfi_valid,
  input                                 rvfi_trap,
  input  [`RISCV_FORMAL_ILEN   - 1 : 0] rvfi_insn,
  input  [`RISCV_FORMAL_XLEN   - 1 : 0] rvfi_pc_rdata,
